def armar(s):
    d = (f"{s['linea1']}\n\n{s['cuerpo']}\n\n{s['pregunta']}\n\n"
         f"Video completo: «{CAT[s['largo']]}»; {s['largo_que']}.\nhttps://www.youtube.com/watch?v={s['largo']}\n"
         f"Sigue con: «{CAT[s['sigue']]}»\nhttps://www.youtube.com/watch?v={s['sigue']}\n"
         f"Para profundizar: {s['pagina']}\n\n{RAYOS}\n\n{AUTOR}\n\n{s['hashtags']}")
    return d


if __name__ == '__main__':
    out = []
    md = [f"# Shorts programados · textos v2 · {datetime.datetime.now().strftime('%Y-%m-%d %Hh%M')}", '',
          'Marco: el video es el pretexto; el texto es el producto. Título = gancho con número (≤ 100 caracteres). Descripción: '
          'línea 1 con la búsqueda y la tesis (lo que se ve sin desplegar), la cuenta en 2 párrafos en la voz de Ricardo, una pregunta '
          'que el director se hace en voz alta, el video completo con una razón para verlo, un segundo video para seguir, la página de '
          'superleads.mx del tema (verificada), el Rayos X (tiene costo; por ahora sin costo) y el bloque de autor. 4 hashtags: '
          '#Admisiones #ColegiosPrivados + 2 del tema.', '']
    for s in S:
        assert len(s['titulo']) <= 100, s['titulo']
        d = armar(s)
        assert len(d) <= 5000
        out.append({'id': s['short'], 'fecha': s['fecha'], 'titulo': s['titulo'], 'descripcion': d, 'largo': s['largo'], 'estado': 'pendiente'})
        md += [f"## {s['fecha']} · https://youtube.com/shorts/{s['short']}", '', f"**Título:** {s['titulo']}", '', '```', d, '```', '']
    json.dump(out, open(os.path.join(AQUI, 'textos_shorts_v2.json'), 'w'), ensure_ascii=False, indent=1)
    open(os.path.join(AQUI, 'SHORTS_textos_v2.md'), 'w').write('\n'.join(md))
    print(len(out), 'textos;', 'títulos máx', max(len(s['titulo']) for s in S), 'chars; descripciones', min(len(o['descripcion']) for o in out), '-', max(len(o['descripcion']) for o in out))
